   "titolo": "Due centri sanitari confinati a Kanyabayonga dopo casi sospetti di Ebola",
   "orig": "Deux centres de santé confinés à Kanyabayonga après la détection de cas suspects d'Ebola",
   "lead": "Due centri sanitari di riferimento nella città di Kanyabayonga, nella zona sanitaria di Kayna (Nord Kivu, Congo), sono sottoposti a un confinamento rigoroso dal 2 ottobre scorso, dopo la segnalazione di due casi sospetti della malattia da virus Ebola. La misura preventiva, prevista per 21 giorni, riguarda almeno 74 persone trattenute sul posto e ha suscitato forte preoccupazione nella popolazione locale.",
   "more": [
    "L'Ebola è una malattia virale emorragica spesso letale, endemica in alcune regioni dell'Africa centrale; il confinamento dei centri sanitari e delle persone esposte è una misura standard per contenere la diffusione del virus durante i focolai."
   ],
