   "id": "z4d540708",
   "sez": "viaggi",
   "titolo": "La Lanterna di Genova, il faro più alto del Mediterraneo che illumina la città da quasi 900 anni",
   "orig": "Da 900 anni illumina l’ingresso alla città: è lui il faro più alto del Mediterraneo",
   "lead": "La Lanterna di Genova è il celebre faro simbolo della città, costruito nel 1128 e alto 77 metri, che lo rendono il più alto faro del Mediterraneo. La struttura si avvicina a un traguardo storico: nel 2028 compirà infatti 900 anni di attività, continuando a segnare l'ingresso al porto genovese come punto di riferimento per i naviganti e come icona riconoscibile del paesaggio urbano della città ligure. Lo riferisce Turisti per Caso.",
   "more": [
    "La Lanterna è da secoli il simbolo di Genova, situata all'ingresso del porto antico. Fari di questo tipo nacquero per guidare le navi in sicurezza verso lo scalo, diventando nel tempo anche monumenti identitari delle città portuali."
   ],
