   "lead": "Nell'ambito del Ravenna Nightmare Film Festival, al Teatro Rasi di Ravenna va in scena l'anteprima nazionale di \"3 Days Rising\", film horror tratto da un racconto di Edgar Allan Poe, interpretato da Mickey Rourke e segnato dall'ultima apparizione cinematografica dell'attore Peter Greene. Lo riferisce San Marino RTV.",
