   "lead": "Robert Smith, leader dei Cure, ha elogiato pubblicamente una nuova versione di un classico della band inglese, definendola \"una delle più sentite e belle cover dei Cure\" che abbia mai ascoltato. Il riconoscimento arriva direttamente dal frontman del gruppo, che ha voluto sottolineare il valore artistico dell'interpretazione data al brano originale. Lo riferisce OndaRock.",
