   "orig": "Creamy Miso Mushroom Pasta",
   "lead": "Una ricetta di pasta cremosa a base di miso e funghi, descritta come il piatto ricco di umami che si vorrà preparare per tutta la stagione. La preparazione punta su un equilibrio di sapori intensi e consistenza avvolgente, pensata per diventare un classico delle cene autunnali. Lo riferisce Bon Appétit.",
