   "orig": "Troye Sivan ha fatto un bel disco, ma il punto è un altro",
   "lead": "Nel nuovo album 'She's the Best', la popstar australiana Troye Sivan racconta sesso, desiderio e fragilità con una naturalezza disarmante, senza ricorrere a scandali o metafore e senza alcuna paura di esporsi. La recensione evidenzia come questo approccio diretto rappresenti il vero valore del disco, al di là della semplice qualità musicale. Lo riferisce Rolling Stone Italia.",
