   "lead": "Lo studio italiano VG13 Architects, fondato da Tommaso Fantini e Alberto Rossi, ha vinto il primo premio del concorso internazionale per il nuovo Stadio Maksimir e il Centro sportivo e ricreativo di Svetice a Zagabria. Il progetto prevede uno stadio da 35.000 posti di categoria UEFA 4 e un intero quartiere dedicato allo sport. Lo riferisce AREA.",
