   "orig": "RAYE sarà la prima headliner di Access All Areas, il nuovo festival di Zalando a Berlino",
   "lead": "La cantante RAYE sarà la prima artista headliner di Access All Areas, il nuovo festival musicale organizzato da Zalando a Berlino, in programma per due giorni nell'aprile 2027 tra Station Berlin e Tempodrom. L'evento potrà accogliere fino a 40.000 persone, con ingresso gratuito riservato ai membri del programma Zalando Plus. Lo riferisce Rolling Stone Italia.",
