   "orig": "Hiking the Polish-Czech Friendship Trail, Where Cold War Dissidents Once Met",
   "lead": "Un reportage racconta il percorso del Sentiero dell'Amicizia polacco-ceca, dove durante la Guerra Fredda i dissidenti dei due paesi si incontravano clandestinamente per discutere delle loro attività contro il regime comunista. L'autore descrive l'esperienza dell'escursione lungo questo itinerario storico al confine tra Polonia e Repubblica Ceca. Lo riferisce The New York Times.",
