   "orig": "Opinion: MyChart said I could opt out of sharing my health data. Figuring out how was maddening",
   "lead": "In un'opinione pubblicata da STAT, Alex Rosenblat racconta la propria esperienza nel tentativo di rifiutare la condivisione dei propri dati sanitari personali attraverso la piattaforma MyChart, scoprendo un processo complicato che avrebbe richiesto persino l'intervento di un notaio. Lo riferisce STAT.",
