   "lead": "Il Consiglio dell'Unione Europea ha posto al centro dei lavori la crisi energetica, insieme a un focus sulla competitività economica del blocco e sulle questioni legate al bilancio comune. L'incontro si inserisce nel dibattito in corso tra gli Stati membri sulle strategie energetiche e di crescita economica europea. Lo riferisce Rai News.",
