   "titolo": "Stagione influenzale: un'esperta spiega sicurezza, efficacia del vaccino e perché vaccinarsi conta",
   "orig": "Flu season is here: Expert explains vaccine safety, effectiveness and why getting vaccinated matters",
   "lead": "Con l'arrivo della stagione influenzale, la professoressa di salute pubblica Denise Hernandez, dell'Università del Texas ad Arlington, incoraggia tutti gli aventi diritto a vaccinarsi, definendo il vaccino antinfluenzale uno dei modi più semplici ed efficaci per proteggere se stessi, la famiglia e la comunità. Secondo l'esperta, il momento migliore per vaccinarsi è adesso. Lo riferisce Medical Xpress.",
   "more": [
    "Il vaccino antinfluenzale viene aggiornato ogni anno per contrastare le varianti del virus dell'influenza in circolazione. Le autorità sanitarie raccomandano generalmente la vaccinazione nei mesi autunnali, prima del picco stagionale, per garantire una protezione adeguata durante i periodi di maggiore diffusione del virus."
   ],
